// Generar respuesta para quejas
const inputData = $input.first().json;
const mensaje = inputData.mensaje || '';
const telefono = inputData.telefono || '';
const nombre = inputData.nombre || '';

// Recuperar datos del cliente y citas previas
const clienteData = inputData;
const citasPrevias = $json;

let respuesta = 'Hola ' + (nombre || '') + ', lamentamos mucho que hayas tenido una mala experiencia. 😔\n\n'
  + 'En *Moto Servicios TIMON* nos tomamos muy en serio tu satisfacción. '
  + 'Hemos registrado tu queja y la revisaremos a la brevedad.\n\n';

// Si hay citas previas, mencionarlas para contexto
if (citasPrevias && citasPrevias.length > 0) {
  respuesta += '📋 *Tus servicios recientes:*\n';
  citasPrevias.forEach(function(cita) {
    respuesta += '  • ' + cita.fecha + ' - ' + (cita.servicio || 'Servicio') + ' (' + (cita.estado || 'Completado') + ')\n';
  });
  respuesta += '\n';
}

respuesta += '🔴 *Tu queja ha sido turnada al área de atención.*\n\n'
  + 'Un asesor se comunicará contigo al número ' + telefono + ' en un máximo de 24 horas hábiles para dar seguimiento a tu caso.\n\n'
  + 'Si deseas hablar directamente con un administrador, puedes llamarnos al 📞 123-456-7890.\n\n'
  + 'Gracias por ayudarnos a mejorar. 🙏';

return [
  {
    json: {
      telefono: telefono,
      mensaje: mensaje,
      respuesta: respuesta,
      categoria: 'QUEJA',
      requiere_atencion: true
    }
  }
];
